#include "mspa/psychology/personality.hpp"
#include <algorithm>
#include <cmath>
namespace mspa { Result<void> PersonalitySystem::normalize(Personality&p)const{float* v[]={&p.sociability,&p.stability,&p.empathy,&p.persistence,&p.curiosity,&p.boldness};for(float*x:v){if(!std::isfinite(*x))return make_error(ErrorCode::InvalidArgument,"personality contains non-finite value");*x=std::clamp(*x,0.0f,1.0f);}return {};} PersonalityDerived PersonalitySystem::derive(const Personality&p)const noexcept{PersonalityDerived d{};d.belief_rigidity=std::clamp(0.65f*p.persistence+0.35f*(1.0f-p.curiosity),0.0f,1.0f);d.goal_persistence=std::clamp(0.8f*p.persistence+0.2f*p.stability,0.0f,1.0f);d.switch_resistance=std::clamp(0.7f*p.persistence+0.3f*p.stability,0.0f,1.0f);d.threat_sensitivity=std::clamp(0.6f*(1.0f-p.stability)+0.4f*(1.0f-p.boldness),0.0f,1.0f);d.social_sensitivity=std::clamp(0.6f*p.sociability+0.4f*p.empathy,0.0f,1.0f);d.exploration=std::clamp(0.7f*p.curiosity+0.3f*p.boldness,0.0f,1.0f);return d;} }
